{%- assign count = periods | size -%}
{%- if count == 1 -%}
<p class="rental-period">{{ periods.first | escape }} only</p>
{%- elsif count > 1 -%}
<p class="rental-period">From {{ periods[0] | escape }} to {{ periods[1] | escape }}</p>
{%- endif -%}

